@Repository
public interface UserRepository extends JpaRepository<User, Long> {
    // Spring Data generates implementations automatically

    List<User> findByEmail(String email); // Returns List, not Iterable

    List<User> findByAgeGreaterThan(int age);

    @Transactional
    void deleteByEmail(String email);
}

@Service
public class UserService {
    private final UserRepository userRepository;

    public UserService(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    public List<User> getAllUsers() {
        return userRepository.findAll(); // Already List<User>
    }

    public User saveAndEnsurePersisted(User user) {
        return userRepository.saveAndFlush(user); // Immediate DB sync
    }
}

@RestController
@RequestMapping("/api/users")
public class UserController {
    private final UserRepository userRepository;

    public UserController(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    @GetMapping
    public Page<User> getUsers(
            @RequestParam(defaultValue = "0") int page,
            @RequestParam(defaultValue = "10") int size,
            @RequestParam(defaultValue = "id") String sortBy) {

        Pageable pageable = PageRequest.of(page, size, Sort.by(sortBy));
        return userRepository.findAll(pageable); // Returns Page<User>
    }

    @GetMapping("/by-age")
    public Page<User> getUsersByAge(
            @RequestParam int minAge,
            @RequestParam(defaultValue = "0") int page) {

        Pageable pageable = PageRequest.of(page, 20);
        return userRepository.findByAgeGreaterThan(minAge, pageable);
    }
}

// 1. Custom interface with method signatures
public interface UserRepositoryCustom {
    List<User> findByDynamicCriteria(String name, Integer minAge, String city);
}

// 2. Implementation class (Impl suffix is mandatory)
@Component
public class UserRepositoryCustomImpl implements UserRepositoryCustom {
    @PersistenceContext
    private EntityManager entityManager;

    @Override
    public List<User> findByDynamicCriteria(String name, Integer minAge, String city) {
        var cb = entityManager.getCriteriaBuilder();
        var query = cb.createQuery(User.class);
        var root = query.from(User.class);

        var predicates = new ArrayList<Predicate>();
        if (name != null) predicates.add(cb.like(root.get("name"), "%" + name + "%"));
        if (minAge != null) predicates.add(cb.ge(root.get("age"), minAge));
        if (city != null) predicates.add(cb.equal(root.get("city"), city));

        query.where(predicates.toArray(new Predicate[0]));
        return entityManager.createQuery(query).getResultList();
    }
}

// 3. Main repository extends both
public interface UserRepository extends JpaRepository<User, Long>, UserRepositoryCustom {
    // Spring Data methods + custom methods merged
}

@Service
public class OrderService {
    private final OrderRepository orderRepository;
    private final InventoryRepository inventoryRepository;
    private final PaymentService paymentService;

    public OrderService(OrderRepository orderRepository,
                        InventoryRepository inventoryRepository,
                        PaymentService paymentService) {
        this.orderRepository = orderRepository;
        this.inventoryRepository = inventoryRepository;
        this.paymentService = paymentService;
    }

    @Transactional // All operations in one transaction
    public Order placeOrder(OrderRequest request) {
        var inventory = inventoryRepository.findById(request.productId())
            .orElseThrow(() -> new ProductNotFoundException());

        inventory.reduceStock(request.quantity()); // Modifies entity
        inventoryRepository.save(inventory);

        var order = new Order(request.productId(), request.quantity());
        orderRepository.save(order);

        paymentService.processPayment(order); // If this fails, entire transaction rolls back
        return order;
    }

    @Transactional(readOnly = true) // Optimization for read-only
    public List<Order> getOrderHistory(Long userId) {
        return orderRepository.findByUserId(userId);
    }
}
